def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)

    while True:
        field = []

        if i < n and line[i] == '"':
            i += 1
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    field.append(c)
                    i += 1
        else:
            while i < n and line[i] != ',':
                field.append(line[i])
                i += 1

        fields.append(''.join(field))

        if i < n and line[i] == ',':
            i += 1
        else:
            break

    return fields
