    result = {}

    def dfs(current, prefix):
        if isinstance(current, dict):
            if not current:
                if prefix:
                    result[prefix] = {}
                return
            for key, value in current.items():
                key_str = str(key)
                new_prefix = f"{prefix}{sep}{key_str}" if prefix else key_str
                dfs(value, new_prefix)
        elif isinstance(current, list):
            if not current:
                if prefix:
                    result[prefix] = []
                return
            for i, value in enumerate(current):
                new_prefix = f"{prefix}{sep}{i}" if prefix else str(i)
                dfs(value, new_prefix)
        else:
            result[prefix] = current

    dfs(obj, "")
    return result
