import re

_ROMAN_PATTERN = re.compile(r'M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})')

def to_roman(n: int) -> str:
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999")
    value = n
    result = []
    for num, sym in [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]:
        while value >= num:
            result.append(sym)
            value -= num
    return ''.join(result)

def from_roman(s: str) -> int:
    if not isinstance(s, str) or not s or not _ROMAN_PATTERN.fullmatch(s):
        raise ValueError("Invalid Roman numeral")
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for c in reversed(s):
        curr = roman_map[c]
        if curr < prev:
            total -= curr
        else:
            total += curr
        prev = curr
    return total
