def top_words(text: str, k: int) -> list[tuple[str, int]]:
    counts: dict[str, int] = {}
    current: list[str] = []

    for ch in text:
        if ch.isalpha():
            current.append(ch.lower())
        else:
            if current:
                word = "".join(current)
                counts[word] = counts.get(word, 0) + 1
                current = []

    if current:
        word = "".join(current)
        counts[word] = counts.get(word, 0) + 1

    result = [(word, count) for word, count in counts.items()]
    result.sort(key=lambda x: (-x[1], x[0]))

    return result[:k]
```

